<template><form @submit.prevent="submit"><label>Название <input v-model.trim="name" /></label><p v-if="nameError" role="alert">{{ nameError }}</p><label>Текст поиска <input v-model.trim="text" /></label><p v-if="textError" role="alert">{{ textError }}</p><label>Регион <input v-model.trim="area" /></label><button type="submit">Сохранить поиск</button></form></template>
<script setup lang="ts">import { ref } from "vue"; const emit=defineEmits<{create:[{name:string;text:string;area:string|null}]}>(); const name=ref("");const text=ref("");const area=ref("");const nameError=ref("");const textError=ref("");function submit(){nameError.value=name.value?"":"Укажите название";textError.value=text.value?"":"Укажите текст поиска";if(!nameError.value&&!textError.value)emit("create",{name:name.value,text:text.value,area:area.value||null});}</script>
